import React, { useState, useEffect } from 'react';
import './App.css';

function App() {
  const [goods, setGoods] = useState([]);
  const [search, setSearch] = useState('');
  const [brandFilter, setBrandFilter] = useState('');
  const [minPrice, setMinPrice] = useState('');
  const [maxPrice, setMaxPrice] = useState('');
  const [minRating, setMinRating] = useState('');
  const [filtered, setFiltered] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    setLoading(true);
    fetch('http://localhost:5000/api/goods/getallgoods')
      .then((res) => {
        if (!res.ok) throw new Error('Network response was not ok');
        return res.json();
      })
      .then((data) => {
        setGoods(Array.isArray(data) ? data : []);
        setLoading(false);
      })
      .catch((err) => {
        setError(err.message || 'Fetch error');
        setLoading(false);
      });
  }, []);

  // build brand list for filter
  const brands = React.useMemo(() => {
    const s = new Set();
    goods.forEach((g) => {
      if (g.brand) s.add(g.brand);
    });
    return ['', ...Array.from(s).sort()];
  }, [goods]);

  useEffect(() => {
    const q = search.trim().toLowerCase();
    const minP = parseFloat(minPrice);
    const maxP = parseFloat(maxPrice);
    const minR = parseFloat(minRating);

    const result = goods.filter((g) => {
      // text match
      const name = (g.name || '').toString().toLowerCase();
      const brand = (g.brand || '').toString().toLowerCase();
      const category = (g.category || '').toString().toLowerCase();
      const itemid = (g.itemid || '').toString().toLowerCase();

      if (q) {
        const textMatch =
          name.includes(q) ||
          brand.includes(q) ||
          category.includes(q) ||
          itemid.includes(q);
        if (!textMatch) return false;
      }

      // brand filter
      if (brandFilter) {
        if ((g.brand || '') !== brandFilter) return false;
      }

      // price range filter
      const price = Number(g.price || 0);
      if (!Number.isNaN(minP) && minPrice !== '' && price < minP) return false;
      if (!Number.isNaN(maxP) && maxPrice !== '' && price > maxP) return false;

      // rating filter
      const rating = Number(g.rating || 0);
      if (!Number.isNaN(minR) && minRating !== '' && rating < minR) return false;

      return true;
    });

    setFiltered(result);
  }, [search, brandFilter, minPrice, maxPrice, minRating, goods]);

  const clearFilters = () => {
    setSearch('');
    setBrandFilter('');
    setMinPrice('');
    setMaxPrice('');
    setMinRating('');
  };

  return (
    <div className="amazon-container">
      <nav className="navbar">
        <div className="logo">MyShop</div>
        <div className="search-wrap">
          <input
            type="text"
            className="search-box"
            placeholder="Search by name, brand, category or id..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>
      </nav>

      <div className="filters">
        <select
          value={brandFilter}
          onChange={(e) => setBrandFilter(e.target.value)}
        >
          <option value="">All brands</option>
          {brands.slice(1).map((b) => (
            <option key={b} value={b}>
              {b}
            </option>
          ))}
        </select>

        <input
          type="number"
          placeholder="Min price"
          value={minPrice}
          onChange={(e) => setMinPrice(e.target.value)}
          min="0"
          step="0.01"
        />
        <input
          type="number"
          placeholder="Max price"
          value={maxPrice}
          onChange={(e) => setMaxPrice(e.target.value)}
          min="0"
          step="0.01"
        />

        <select
          value={minRating}
          onChange={(e) => setMinRating(e.target.value)}
        >
          <option value="">Any rating</option>
          <option value="0">0+</option>
          <option value="1">1+</option>
          <option value="2">2+</option>
          <option value="3">3+</option>
          <option value="4">4+</option>
          <option value="5">5</option>
        </select>

        <button className="clear-btn" onClick={clearFilters}>
          Clear
        </button>
      </div>

      <main className="content">
        {loading ? (
          <div className="info">Loading goods...</div>
        ) : error ? (
          <div className="error">Error: {error}</div>
        ) : filtered.length === 0 ? (
          <div className="info">No goods found.</div>
        ) : (
          <div className="goods-grid">
            {filtered.map((good) => (
              <div key={good._id || good.itemid} className="good-card">
                <div className="good-image-wrap">
                  {good.imageUrl && good.imageUrl.length > 0 ? (
                    <img
                      src={good.imageUrl[0]}
                      alt={good.name}
                      className="good-image"
                    />
                  ) : (
                    <div className="image-placeholder">No image</div>
                  )}
                </div>
                <div className="good-info">
                  <div className="good-name">{good.name}</div>
                  <div className="good-brand">{good.brand}</div>
                  <div className="good-category">{good.category}</div>
                  <div className="good-price">
                    ${Number(good.price || 0).toFixed(2)}
                  </div>
                  <div className="good-rating">
                    Rating: {good.rating ?? 'N/A'}
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </main>
    </div>
  );
}

export default App;
